#!/bin/bash
# The public build's own copy (HD_PUBLIC=1), so the flag build in build-s18 keeps serving the e2e. Same commit: site/ is
# re-extracted from git (3013d630) so nothing generated by the flag build leaks in; node_modules and the supplier-image
# cache hard-linked (read-only use); the repo dirs the build reads are links to the clean copy's (data/, status/, docs/,
# .github/, assets/, qa/, studio: the build never writes there).
set -euo pipefail
REPO=/home/user/homedesign-app
QA=$(cd "$(dirname "$0")/.." && pwd)
SRC=$QA/build-s18
DST=$QA/build-s18-${1:-pub}
[ -e "$DST" ] && { echo "exists: $DST"; exit 1; }
mkdir -p "$DST"
git -C "$REPO" archive 3013d630 site | tar -x -C "$DST"
cp -al "$SRC/site/node_modules" "$DST/site/node_modules"
for w in api web; do [ -d "$SRC/site/$w/node_modules" ] && cp -al "$SRC/site/$w/node_modules" "$DST/site/$w/node_modules"; done
mkdir -p "$DST/site/.cache" && cp -al "$SRC/site/.cache/supplier-images" "$DST/site/.cache/supplier-images"
for d in data status docs .github assets qa studio; do ln -s "$SRC/$d" "$DST/$d"; done
echo "copy -> $DST"
